package com.fula.exploringchina.components

import com.tencent.kuikly.core.base.*
import com.tencent.kuikly.core.views.*
import com.fula.exploringchina.theme.YijianColors
import com.fula.exploringchina.theme.YijianTheme

/**
 * ProgressBar 属性
 */
internal class ProgressBarAttr : ComposeAttr() {
    var progress: Float = 0f          // 0.0 ~ 1.0
    var trackColor: Color = YijianColors.progressTrack
    var fillColor: Color = YijianColors.progressFill
    var thumbColor: Color = YijianColors.progressThumb
    var showThumb: Boolean = true
    var barHeight: Float = YijianTheme.BarHeight.progressBar
    var enableDrag: Boolean = true
}

/**
 * ProgressBar 事件
 */
internal class ProgressBarEvent : ComposeEvent() {
    var onProgressChanged: ((Float) -> Unit)? = null
}

/**
 * 自定义进度条组件
 * 支持拖动交互
 */
internal class ProgressBarView : ComposeView<ProgressBarAttr, ProgressBarEvent>() {

    override fun createAttr(): ProgressBarAttr = ProgressBarAttr()

    override fun createEvent(): ProgressBarEvent = ProgressBarEvent()

    override fun body(): ViewBuilder {
        val ctx = this
        val totalWidth = pagerData.pageViewWidth
        return {
            View {
                attr {
                    size(totalWidth, ctx.attr.barHeight + 20f)
                    allCenter()
                }

                // 轨道背景
                View {
                    attr {
                        size(totalWidth - 40f, ctx.attr.barHeight)
                        backgroundColor(ctx.attr.trackColor)
                        borderRadius(ctx.attr.barHeight / 2)
                        flexDirectionRow()
                        alignItemsCenter()
                    }

                    // 已播放进度
                    View {
                        attr {
                            width((totalWidth - 40f) * ctx.attr.progress.coerceIn(0f, 1f))
                            height(ctx.attr.barHeight)
                            backgroundColor(ctx.attr.fillColor)
                            borderRadius(ctx.attr.barHeight / 2)
                        }
                    }

                    // 拖动滑块
                    if (ctx.attr.showThumb && ctx.attr.progress > 0f) {
                        View {
                            attr {
                                size(16f, 16f)
                                borderRadius(8f)
                                backgroundColor(ctx.attr.thumbColor)
                                absolutePosition(
                                    left = (totalWidth - 40f) * ctx.attr.progress.coerceIn(0f, 1f) - 8f + 20f,
                                    top = (ctx.attr.barHeight + 20f - 16f) / 2f
                                )
                                boxShadow(BoxShadow(0f, 0f, 4f, Color(0x80000000)))
                            }
                        }
                    }
                }
            }
        }
    }
}

/**
 * 扩展方法
 */
internal fun ViewContainer<*, *>.ProgressBar(init: ProgressBarView.() -> Unit) {
    addChild(ProgressBarView(), init)
}

package com.fula.exploringchina.components

import com.tencent.kuikly.core.base.*
import com.tencent.kuikly.core.log.KLog
import com.tencent.kuikly.core.views.*
import com.fula.exploringchina.manager.DraftManager
import com.fula.exploringchina.theme.YijianColors

/**
 * 底部操作栏 — 选中模式时覆盖 Tab Bar
 *
 * ┌─────────────────────────────────────┐
 * │         │                            │
 * │  全选    │         删除(N)            │
 * │         │                            │
 * └─────────────────────────────────────┘
 *
 * 直接持有 [DraftManager] 引用，使 attr{} 能追踪 observable 字段
 * 实现响应式重绘（selectedCount / isAllSelected 变化时自动更新文字和颜色）。
 */
internal fun ViewContainer<*, *>.DraftActionBar(
    mgr: DraftManager,
    safeAreaBottom: Float,
) {
    View {
        attr {
            height(56f + safeAreaBottom)
            backgroundColor(Color(0xFF1E1E1E))
            flexDirectionRow()
            alignItemsCenter()
            paddingBottom(safeAreaBottom)
        }

        // 全选/反选 — attr{} 读取 mgr.isAllSelected（observable），自动追踪
        View {
            attr { flex(1f); allCenter() }
            event {
                click {
                    KLog.d("DraftBar", "toggleAll clicked, isAllSelected=${mgr.isAllSelected}")
                    if (mgr.isAllSelected) mgr.deselectAll() else mgr.selectAll()
                }
            }
            Text {
                attr {
                    text(if (mgr.isAllSelected) "反选" else "全选")
                    fontSize(15f)
                    color(YijianColors.textPrimary)
                }
            }
        }

        // 分割线
        View { attr { width(1f); height(30f); backgroundColor(YijianColors.surfaceLight) } }

        // 删除 — attr{} 读取 mgr.selectedCount（observable），自动追踪
        View {
            attr { flex(1f); allCenter() }
            event {
                click {
                    if (mgr.selectedCount > 0) mgr.remove(mgr.selectedIds.toList())
                }
            }
            Text {
                attr {
                    text(if (mgr.selectedCount > 0) "删除(${mgr.selectedCount})" else "删除")
                    fontSize(15f)
                    color(if (mgr.selectedCount > 0) Color(0xFFFF3B30) else Color(0xFF666666))
                }
            }
        }
    }
}

