/**
 * 顶部导航栏组件
 * 仿剪映风格 — 深色背景，左侧返回按钮，中央标题
 */
internal class TopBarView : ComposeView<TopBarAttr, TopBarEvent>() {

    override fun createAttr(): TopBarAttr = TopBarAttr()

